INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule, typical_rate_example) VALUES (308, 1, 70, 1, 80.00, 5.00, 20.0, '[]', '合同有效期内可书面申请减少基本保险金额，减少部分视为终止合同，退还减少部分对应的现金价值', '不支持加保', '不支持第二投保人', 3254000.0, '{"身故保险金": "被保险人身故时，按本合同的基本保险金额给付身故保险金", "活力分达标额外身故保险金": "基本保险金额 x 已获取活力分达标次数之和 x 2%（最高10次，即额外20%保额）", "活力分达标标准": "每个保单年度内活力分>=70分的天数累计>=180天即为达标，每个保单年度最多获取1次", "活力分锁定": "自第10个保单周年日起或被保险人年满60周岁后首个保单周年日起（以较早者为准），达标次数不再变化", "活力分平台": "通过中英人寿指定活力分记录平台记录运动健康数据"', '18岁男，标准体，趸交，每千元保额年交325.4元'); -- 中英人寿心爱永恒（悦动版）终身寿险（分红型）
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, death_payout_rule, typical_rate_example) VALUES (309, 1, 70, 1, 80.00, 5.00, 0, '[]', '可书面申请减少基本保险金额，退还减少部分对应现金价值', '不支持', '支持', '18周岁前：现金价值与已交保险费较高者；18-71周岁：现金价值、基本保额×2、已交保费×年龄比例三者较高者；71周岁后：现金价值、基本保额、已交保费×年龄比例三者较高者。年龄比例：18-41岁160%，42-61岁140%，62岁及以上120%。另含航空公共交通工具意外身故保险金（基本保额×2，最高2000万）。方案一不含全残，方案二含全残（赔付规则同身故）', '18岁男，标准体，趸交，每千元保额年交166.5元'); -- 中英人寿爱永恒终身寿险A款（分红型）
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (310, 1, 70, 1, 80.00, 5.00, 0, '[]', '合同有效期内可书面申请减少基本保险金额，减少部分视为终止合同，退还减少部分对应的现金价值；减少交清增额基本保险金额需一次性办理累计交清增额基本保险金额的减保', '不支持加保', '支持。投保人与被保险人非同一人时可申请指定第二投保人，须满足：1.与被保险人有保险利益关系；2.经被保险人书面同意。投保人身故后第二投保人可申请变更为投保人', 2608000.0, '{"方案一（身故+航空意外）": {"18周岁前身故": "max(现金价值, 已交保费)", "18周岁后身故": "max(现金价值, 基本保险金额, 已交保费 x 比例)", "比例": "18-41周岁160%，42-61周岁140%，62周岁及以上120%"}, "方案二（身故+航空意外+全残）": {"18周岁前": "max(现金价值, 已交保费)", "18周岁至71周岁前": "max(现金价值, 基本保险金额的2倍, 已交保费 x 比例)", "71周岁后": "max(现金价值, 基'); -- 中英人寿爱永恒美式终身寿险（分红型）
