INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (372, 1, 70, 1, 80.00, 5.00, 2.5, '[]', '{"规则1_时间要求": "合同生效或最后一次复效之日起满5年方可申请减保", "规则2_额度限制": "每个保单年度累计减少的基本保险金额之和不得超过合同生效时基本保险金额的20%", "规则3_最低标准": "减少后基本保险金额和保险费不得低于减保当时公司规定的最低标准", "规则4_退保处理": "基本保险金额减少的部分视为退保，退还减少部分对应的现金价值"}', '条款中未明确约定加保规则（基本保险金额变更仅涉及减少）', '条款中未提及第二投保人功能', 30.0, '{"说明": "分三档给付，取较大值", "到达年龄17周岁及以前": "所交保险费 与 基本保险金额对应的现金价值 两者较大者", "到达年龄18周岁及以后且交费期间未满": "所交保费×对应比例 与 基本保险金额对应的现金价值 两者较大者", "到达年龄18周岁及以后且交费期间已满": "所交保费×对应比例、基本保险金额对应的现金价值、有效保险金额 三者较大者", "比例表": {"18-40周岁": "160%", "41-60周岁": "140%", "61周岁以上": "120%"}, "所交保'); -- 复星保德信星福家终身寿险（分红型）
