INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (374, 1, 70, 1, 80.00, 5.00, 2.0, '[]', '{"规则1_时间要求": "合同生效或最后一次复效之日起满5年方可申请减保", "规则2_额度限制": "每个保单年度累计减少的基本保险金额之和不得超过合同生效时基本保险金额的20%", "规则3_最低标准": "减少后基本保险金额和保险费不得低于减保当时公司规定的最低标准", "规则4_退保处理": "减保后按减少后的基本保险金额以及累计增额红利承担对应的保险责任，计算保单红利。退还：合同的现金价值乘以基本保险金额减少比例 + 终了红利（若有）乘以基本保险金额减少比例"}', '条款中未明确约定加保规则（基本保险金额变更仅涉及减少）', '条款中未提及第二投保人功能', 30.0, '{"说明": "分三档给付，取较大值", "到达年龄17周岁及以前": "所交保险费 与 基本保险金额对应的现金价值 两者较大者", "到达年龄18周岁及以后且交费期间未满": "所交保费×对应比例 与 基本保险金额对应的现金价值 两者较大者", "到达年龄18周岁及以后且交费期间已满": "所交保费×对应比例、基本保险金额对应的现金价值、有效保险金额 三者较大者", "比例表": {"18-40周岁": "160%", "41-60周岁": "140%", "61周岁以上": "120%"}, "所交保'); -- 复星保德信星福家青鸾版终身寿险（分红型）
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (375, 1, 70, 1, 80.00, 5.00, 105.0, '[]', '{"说明": "犹豫期后可申请减少基本保险金额，需满足：1.合同生效或最后一次复效之日起满5年；2.每个保单年度累计减少的基本保险金额之和不得超过合同生效时基本保险金额的20%；3.减保后基本保险金额和保险费不得低于最低标准。减保部分视为退保"}', '{"说明": "条款中未提及加保规则，不支持加保"}', '{"说明": "条款及投保规则中未提及第二投保人相关规则"}', 30.0, '{"未成年身故（不满18周岁）": "所交保险费与现金价值二者取高", "成年后缴费期内身故": "所交保险费×比例与现金价值二者取高", "成年后缴费期后身故": "当年度有效保险金额、现金价值、所交保险费×比例三者取高", "赔付比例表": {"18周岁-40周岁": "160%", "41周岁-60周岁": "140%", "61周岁以上": "120%"}, "额外保障": {"说明": "本产品无额外意外身故/全残保险金保障"}, "全残保障": "本合同承担全残保险金，赔付规则与身故保险金相同'); -- 复星保德信星福家龙腾版终身寿险（分红型）
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_start_year, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (428, 1, 70, 1, 80.00, 5.00, 0, '[]', 5, '自第5个保单周年日起可申请减保，每保单年度累计减少的基本保险金额不得超过投保时基本保险金额的20%', '未明确', '犹豫期满后可指定第二投保人；被保险人不满18岁或无完全民事行为能力时，指定其父亲或母亲；被保险人满18岁且有完全民事行为能力时，指定被保险人本人', 26.5, '18岁前身故：取累计已交保费（不计息）与现金价值的较大者；18岁后身故：取基本保险金额与累计已交保费乘以给付比例（18-40岁160%、41-60岁140%、61岁及以上120%）的较大者'); -- 瑞泰鸿利传世（致享版）终身寿险（分红型）
