INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_start_year, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (430, 1, 70, 1, 80.00, 5.00, 1.5, '[]', 5, '自第5个保单周年日起可申请减保，每保单年度累计减少的基本保险金额不得超过投保时基本保险金额的20%', '未明确', '犹豫期满后可指定第二投保人；被保险人不满18岁或无完全民事行为能力时，指定其父亲或母亲；被保险人满18岁且有完全民事行为能力时，指定被保险人本人', 82545000.0, '18岁前身故/全残：取累计已交保费（不计息）与现金价值较大者；18岁后且交费期满前：取累计已交保费乘以给付比例与现金价值较大者；18岁后且交费期满后：取有效保险金额、累计已交保费乘以给付比例、现金价值三者较大者。给付比例：0-17岁100%、18-40岁160%、41-60岁140%、61岁及以上120%'); -- 瑞泰鸿利多多终身寿险（分红型）
