INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (441, 1, 70, 1, 80.00, 5.00, 1.75, '[]', '每个保单年度内累计减少的基本保险金额以投保时保险单上载明的基本保险金额的20%为限。减保后，基本保险金额和保险费须符合保险公司当时的规定。', '条款中未明确约定加保规则，以保司实际规则为准', '可指定第二投保人。被保险人为两人或当投保人与唯一的被保险人不为同一人时，投保人有权指定第二投保人。第二投保人须为自然人，须经过被保险人（或其监护人）以及第二投保人本人的书面同意，且与被保险人具有保险利益关系。第二投保人应在投保人身故后两年内提出变更投保人申请。', 1000.0, '{"18周岁前身故/全残": "现金价值与已交保险费（无息）的较大者", "18周岁后交费期间内身故/全残": "现金价值与已交保险费（无息）×给付比例的较大者", "18周岁后交费期满后身故/全残": "现金价值、已交保险费（无息）×给付比例、当年度保险金额三者取大"}'); -- 长城山海关永乐典藏版终身寿险（分红型）（单人版）
