INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (577, 1, 70, 1, 80.00, 5.00, 3.6, '[]', '{"说明": "条款1.5条规定可变更基本保险金额（含减保），但需符合公司届时的规则，未明确具体减保比例限制"}', '{"说明": "条款1.5条规定可变更基本保险金额（含加保），但需符合公司届时的规则，未明确具体加保条件"}', '{"说明": "条款及投保规则中未提及第二投保人相关规则"}', 30.0, '{"未成年身故（不满18周岁）": "现金价值与已交保费二者取高", "成年后缴费期内身故": "现金价值与已交保费×比例二者取高", "成年后缴费期后身故": "当年度保险金额、现金价值、已交保费×比例三者取高", "赔付比例表": {"已满18周岁未满41周岁": "160%", "已满41周岁未满61周岁": "140%", "已满61周岁": "120%"}, "额外保障": {"航空公共交通工具意外身故或全残保险金": "基本保险金额1倍（限75周岁前）", "公共交通工具意外身故或全残保险金"'); -- 中英人寿传世鑫玺终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (578, 1, 70, 1, 80.00, 5.00, 1.0, '[]', '合同有效期内可书面申请减少基本保险金额，减少后的基本保险金额不得低于规定的最低承保金额；减少部分视为终止合同，退还减少部分对应的现金价值', '不支持加保', '条款未提及', 12000000.0, '{"18周岁前": "现金价值 与 已缴保费（取较高者）", "18周岁后且缴费期间内": "现金价值 与 已缴保费×对应比例（取较高者）", "18周岁后且缴费期间届满后": "现金价值、有效保额（基本保额×(1+3.1%)^(n-1)）、已缴保费×对应比例（取三者中最高者）", "年龄比例_18-40周岁": "160%", "年龄比例_41-60周岁": "140%", "年龄比例_61周岁及以上": "120%", "全残保障": "支持，全残保险金给付规则与身故保险金相同"}'); -- 中英人寿安鑫传家终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_start_year, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (579, 1, 70, 1, 80.00, 5.00, 3.5, '[]', 5, '自合同生效后第5个保单周年日（含）起可申请减保；同一保单年度内减保金额对应的现金价值之和不得超过实际已缴保险费总额的20%；减少后基本保险金额对应保费不得低于规定的最低金额', '不支持加保', '条款未提及', 9650000.0, '{"18周岁前": "现金价值 与 已缴保费（取较高者）", "18周岁后且缴费期间内": "现金价值 与 已缴保费×对应比例（取较高者）", "18周岁后且缴费期间届满后": "当年度保险金额、现金价值、已缴保费×对应比例（取三者中最高者）", "年龄比例_18-40周岁": "160%", "年龄比例_41-60周岁": "140%", "年龄比例_61周岁及以上": "120%", "全残保障": "支持，全残保险金给付规则与身故保险金相同", "航空公共交通意外额外赔付": "乘坐航空公共交通工具'); -- 中英人寿尊享传家终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_start_year, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (580, 1, 70, 1, 80.00, 5.00, 3.5, '[]', 5, '自合同生效后第5个保单周年日（含）起可申请减保；同一保单年度内减保金额之和不得超过投保时保单上载明的基本保险金额的20%；减少后基本保险金额对应保费不得低于规定的最低金额', '不支持加保', '条款未提及', 9650000.0, '{"18周岁前": "现金价值 与 已缴保费（取较高者）", "18周岁后且缴费期间内": "现金价值 与 已缴保费×对应比例（取较高者）", "18周岁后且缴费期间届满后": "当年度保险金额、现金价值、已缴保费×对应比例（取三者中最高者）", "年龄比例_18-40周岁": "160%", "年龄比例_41-60周岁": "140%", "年龄比例_61周岁及以上": "120%", "全残保障": "支持，全残保险金给付规则与身故保险金相同", "航空公共交通意外额外赔付": "乘坐航空公共交通工具'); -- 中英人寿尊享传家（庆典版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (581, 1, 70, 1, 80.00, 5.00, 0, '[]', '可书面申请减少基本保险金额，减少部分视为终止合同，退还减少部分对应的现金价值；无年度减保20%的限制（不同于增额终身寿险）', '不支持加保', '条款未提及第二投保人', 10000.0, '{"18周岁前身故": "max(被保险人身故时的现金价值, 基本保险金额所对应的已交保险费)", "18周岁后身故": "按基本保险金额给付身故保险金（定额给付，不区分交费期内/外）", "比例": "不适用（18周岁后直接给付基本保险金额）", "航空公共交通工具意外身故保险金": "乘坐航空公共交通工具遭遇交通意外伤害事故，180天内身故，额外给付基本保险金额的200%，累计最高2000万元", "公共交通工具意外身故保险金": "18周岁后，乘坐轨道/公共汽车/水上公共交通工具遭遇交通意外伤害事故'); -- 中英人寿心爱永恒终身寿险
