INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (594, 1, 70, 1, 80.00, 5.00, 3.0, '[]', '{"规则描述": "自合同生效后的第五个保单周年日（含）起可申请减保。同一个保单年度内申请减少的基本保险金额之和，不得超过投保时基本保险金额的20%，且减少后的基本保险金额对应保费不得低于最低金额。", "减保处理": "基本保险金额的减少部分视为终止合同，退还减少部分对应的现金价值。", "条款依据": "1.5 基本保险金额、当年度保险金额与申请减少基本保险金额"}', '{"说明": "条款及投保规则中未提及加保规则，本产品不支持加保。"}', '{"说明": "条款及投保规则中未提及第二投保人相关规则"}', 30.0, '{"未成年身故（不满18周岁）": "现金价值与已缴保费二者取高", "成年后缴费期内身故": "现金价值与已缴保费×比例二者取高", "成年后缴费期后身故": "当年度保险金额、现金价值、已缴保费×比例三者取高", "赔付比例表": {"已满18周岁未满41周岁": "160%", "已满41周岁未满61周岁": "140%", "已满61周岁": "120%"}, "额外保障": {"公共交通工具意外身故保险金": "基本保险金额的50%（限18周岁后、75周岁前，含轨道/公共汽车/水上公共交通工具，'); -- 中英人寿鑫享未来2号终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (595, 1, 70, 1, 80.00, 5.00, 3.0, '[]', '{"规则描述": "自合同生效后的第五个保单周年日（含）起可申请减保。同一个保单年度内申请减少的基本保险金额之和，不得超过投保时基本保险金额的20%，且减少后的基本保险金额对应保费不得低于最低金额。", "减保处理": "基本保险金额的减少部分视为终止合同，退还减少部分对应的现金价值。", "条款依据": "1.6 基本保险金额、当年度保险金额与申请减少基本保险金额"}', '{"说明": "条款及投保规则中未提及加保规则，本产品不支持加保。"}', '{"说明": "条款及投保规则中未提及第二投保人相关规则"}', 30.0, '{"未成年身故（不满18周岁）": "现金价值与已交保费二者取高", "成年后缴费期内身故": "现金价值与已交保费×比例二者取高", "成年后缴费期后身故": "当年度保险金额、现金价值、已交保费×比例三者取高", "赔付比例表": {"已满18周岁未满41周岁": "160%", "已满41周岁未满61周岁": "140%", "已满61周岁": "120%"}, "额外保障": {"航空公共交通工具意外身故保险金": "基本保险金额的100%（限75周岁前，累计最高以1000万元为限）", "公共交'); -- 中英人寿鑫享未来3.0终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_start_year, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (596, 1, 70, 1, 80.00, 5.00, 3.0, '[]', 5, '自合同生效后的第5个保单周年日（含）起，方可书面申请减少基本保险金额。同一保单年度内申请减少的基本保险金额之和，不得超过投保时保险单上载明的基本保险金额的20%，且减少后的基本保险金额对应保险费不得低于规定的最低金额', '不支持加保', '条款未提及第二投保人', 1000000.0, '{"未成年（不满18周岁）": "max(基本保险金额所对应的现金价值, 基本保险金额所对应的已交保险费)", "成年且在交费期间届满后首个保单周年日之前（含）": "max(基本保险金额所对应的现金价值, 基本保险金额所对应的已交保险费x比例)", "成年且在交费期间届满后首个保单周年日之后（不含）": "max(当年度保险金额, 基本保险金额所对应的现金价值, 基本保险金额所对应的已交保险费x比例)", "赔付比例表": {"已满18周岁未满41周岁": "160%", "已满41周岁未满61周岁":'); -- 中英人寿鑫享未来3.0（至臻版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_start_year, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (597, 1, 70, 1, 80.00, 5.00, 3.5, '[]', 5, '自合同生效后的第5个保单周年日（含）起，方可书面申请减少基本保险金额。同一保单年度内申请减少的基本保险金额对应的现金价值之和，不得超过本合同实际已缴保险费总额的20%，且减少后的基本保险金额对应保险费不得低于规定的最低金额', '不支持加保', '条款未提及第二投保人', 1000000.0, '{"未成年（不满18周岁）": "max(现金价值, 基本保险金额所对应的已缴保险费)", "成年且在交费期间届满后首个保单周年日之前（含）": "max(现金价值, 基本保险金额所对应的已缴保险费x比例)", "成年且在交费期间届满后首个保单周年日之后（不含）": "max(当年度保险金额, 现金价值, 基本保险金额所对应的已缴保险费x比例)", "赔付比例表": {"已满18周岁未满41周岁": "160%", "已满41周岁未满61周岁": "140%", "已满61周岁": "120%"}, "公'); -- 中英人寿鑫享未来终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list) VALUES (598, 1, 70, 1, 80.00, 5.00, 0, '[]'); -- 中英人寿鑫满意2026终身寿险（万能型）
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (599, 1, 70, 1, 80.00, 5.00, 0, '[]', '可书面申请减少基本保险金额，减少部分视为终止合同，退还减少部分对应的现金价值；无年度减保20%的限制（不同于增额终身寿险）', '不支持加保', '条款未提及第二投保人', 1000000.0, '{"未成年（不满18周岁）": "max(现金价值, 基本保险金额所对应的已交保险费)", "成年后（满18周岁含）": "按基本保险金额给付身故保险金（定额给付，不区分交费期内/外，不设比例系数）", "比例": "不适用（18周岁后直接给付基本保险金额）", "航空公共交通工具意外身故保险金": "乘坐航空公共交通工具遭遇交通意外伤害事故，180天内身故，额外给付基本保险金额的200%，累计最高2000万元", "公共交通工具意外身故保险金": "18周岁后，乘坐轨道/公共汽车/水上公共交通工具遭遇交'); -- 中英人寿鑫爱永恒3.0终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list) VALUES (600, 1, 70, 1, 80.00, 5.00, 0, '[]'); -- 中英人寿鑫爱永恒终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list) VALUES (601, 1, 70, 1, 80.00, 5.00, 0, '[]'); -- 中英人寿鑫盈家终身寿险C款_互联网
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (602, 1, 70, 1, 80.00, 5.00, 2.0, '[]', '同一保单年度内申请减少的基本保险金额之和，不得超过投保时保险单上载明的基本保险金额的20%。减少后的基本保险金额对应保险费不得低于申请减少时保险公司规定的最低金额。', '条款中未提及加保权益。', '{"是否支持": "是", "规则说明": "投保人与被保险人非同一人时，可书面申请指定第二投保人。第二投保人须为自然人，且（1）与被保险人具有保险利益关系；（2）经被保险人（或其监护人）书面同意。投保人身故后，第二投保人可申请变更为投保人。投保人变更或第二投保人身故时，原指定自动撤销。投保人可经被保险人书面同意后撤销指定。"}', 40.0, '{"保障类型": "身故或全残保险金", "18周岁前身故或全残": "取（1）基本保险金额所对应的现金价值 与 （2）基本保险金额所对应的已交保险费 两者较高者", "18周岁后身故或全残（交费期间届满后的首个保单周年日之前含该日）": "取（1）基本保险金额所对应的现金价值 与 （2）已交保险费×对应比例 两者较高者", "18周岁后身故或全残（交费期间届满后的首个保单周年日之后不含该日）": "取（1）当年度保险金额、（2）基本保险金额所对应的现金价值、（3）已交保险费×对应比例 三者最高者", "'); -- 中英人寿鑫盈家终身寿险C款（互联网）
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, cross_generation, min_premium, death_payout_rule) VALUES (603, 1, 70, 1, 80.00, 5.00, 2.5, '[]', '同一保单年度内申请减少的基本保险金额之和，不得超过投保时保险单上载明的基本保险金额的20%。减少后的基本保险金额对应保险费不得低于申请减少时保险公司规定的最低金额。', '条款中未提及加保权益。', '条款中未设第二投保人条款（普通版条款目录中无第二投保人章节，区别于C款）。', 1, 40.0, '{"保障类型": "身故保险金（含特定公共交通工具意外身故保险金）", "18周岁前身故": "取（1）基本保险金额所对应的现金价值 与 （2）基本保险金额所对应的已交保险费 两者较高者", "18周岁后身故（交费期间届满后的首个保单周年日之前含该日）": "取（1）基本保险金额所对应的现金价值 与 （2）已交保险费×对应比例 两者较高者", "18周岁后身故（交费期间届满后的首个保单周年日之后不含该日）": "取（1）当年度保险金额、（2）基本保险金额所对应的现金价值、（3）已交保险费×对应比例 三者最'); -- 中英人寿鑫盈家终身寿险（互联网）
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_times_limit, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (604, 1, 70, 1, 80.00, 5.00, 3.2, '[]', 1, '可书面申请减少基本保险金额，减少后的基本保险金额不得低于申请时保险公司规定的最低承保金额。未设定每年度20%的减保比例限制（相比鑫盈家系列限制更少）。', '条款中未提及加保权益。', '{"是否支持": "否", "规则说明": "条款中未设第二投保人条款。"}', 0.0, '{"保障类型": "身故或全残保险金", "18周岁前身故或全残": "取（1）本合同的现金价值 与 （2）基本保险金额所对应的已缴保险费 两者较高者", "18周岁后身故或全残（交费期间届满后的首个保单周年日之前含该日）": "取（1）本合同的现金价值 与 （2）已缴保险费×对应比例 两者较高者", "18周岁后身故或全残（交费期间届满后的首个保单周年日之后不含该日）": "取（1）本合同的现金价值、（2）基本保险金额×(1+3.2%)^(n-1)、（3）已缴保险费×对应比例 三者最高者", "赔付比例'); -- 中英鑫玺世家终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (685, 1, 70, 1, 80.00, 5.00, 1.0, '[]', '{"说明": "条款中未提及减保限制规则（该产品为老产品，条款无明确的减保20%限制）"}', '{"说明": "支持加保，有两种方式：1.被保险人年满75周岁前的首个保单周年日前，可通过额外支付一次性保费增加基本保险金额；2.交费年期未满的，在第2个保单周年日（含）后至第10个保单周年日（不含）前，可增加基本保险金额，每年增加以原投保时基本保险金额的50%为限"}', '{"说明": "条款及投保规则中未提及第二投保人相关规则"}', 30.0, '{"未成年身故（不满18周岁）": "实际交纳的保险费与现金价值二者取高", "成年后缴费期内身故": "实际交纳的保险费×比例与现金价值二者取高", "成年后缴费期后身故": "实际交纳的保险费×比例、现金价值、有效保险金额三者取高", "赔付比例表": {"18周岁-40周岁": "160%", "41周岁-60周岁": "140%", "61周岁以上": "120%"}, "额外保障": {"说明": "本产品无额外意外身故/全残保险金保障"}, "全残保障": "本合同承担全残保险金，赔付规则与身'); -- 复星保德信星世家终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list) VALUES (686, 1, 70, 1, 80.00, 5.00, 1.0, '[]'); -- 复星保德信星佑家终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (687, 1, 70, 1, 80.00, 5.00, 1.0, '[]', '{"说明": "条款中未提及减保限制规则（该产品为老产品，条款无明确的减保20%限制）"}', '{"说明": "支持加保，有两种方式：1.被保险人年满60周岁前的首个保单周年日前，可通过额外支付一次性保费增加基本保险金额；2.交费年期未满的，在第2个保单周年日（含）后至第5个保单周年日（不含）前，可增加基本保险金额，每年增加以原投保时基本保险金额的50%为限"}', '{"说明": "条款及投保规则中未提及第二投保人相关规则"}', 30.0, '{"未成年身故（不满18周岁）": "实际交纳的保险费与现金价值二者取高", "成年后缴费期内身故": "实际交纳的保险费×比例与现金价值二者取高", "成年后缴费期后身故": "实际交纳的保险费×比例、现金价值、有效保险金额三者取高", "赔付比例表": {"18周岁-40周岁": "160%", "41周岁-60周岁": "140%", "61周岁以上": "120%"}, "额外保障": {"说明": "本产品无额外意外身故/全残保险金保障"}, "全残保障": "本合同承担全残保险金，赔付规则与身'); -- 复星保德信星御家终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, cross_generation, min_premium, death_payout_rule) VALUES (688, 1, 70, 1, 80.00, 5.00, 3.5, '[]', '{"说明": "条款中无明确的减保条款。条款6.4为基本保险金额变更（加保），另有6.3减额交清（一次性减额交清非减保）。", "减额交清": "可在有效期内申请减额交清，以当时现金价值扣除欠款后余额作为一次性净保费，重新计算基本保险金额"}', '{"规则1": "被保险人年满60周岁后的首个保单周年日（不含）前，可通过额外支付一次性保费增加基本保险金额，按增加时的年龄计算保费", "规则2": "第2个保单周年日（含）至第5个保单周年日（不含）前，可增加基本保险金额，增加部分按原投保时年龄计算，但须补交保费。每年增加的基本保险金额以原投保时基本保险金额的50%为限", "限制": "已变更为减额交清或保费已被豁免的，不接受增加基本保险金额的申请"}', '不支持。条款中无第二投保人相关约定', 1, 993.0, '{"18周岁前身故": "取以下两项较大者：(1)实际交纳的保险费；(2)现金价值", "18周岁后身故且交费期未满": "取以下两项较大者：(1)实际交纳的保险费×比例（18-40周岁160%，41-60周岁140%，61周岁以上120%）；(2)现金价值", "18周岁后身故且交费期已满": "取以下三项较大者：(1)实际交纳的保险费×比例（18-40周岁160%，41-60周岁140%，61周岁以上120%）；(2)现金价值；(3)基本保险金额×(1+3.5%)^(保单年度数-1)"}'); -- 复星保德信星瑞家终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (689, 1, 70, 1, 80.00, 5.00, 2.5, '[]', '{"规则1": "合同生效或最后一次复效之日起满5年后方可申请减保", "规则2": "每个保单年度累计减少的基本保险金额之和不得超过本合同生效时基本保险金额的20%", "规则3": "基本保险金额减少后，基本保险金额和保险费不得低于减保当时规定的最低标准", "减保效果": "基本保险金额减少的部分视为退保，退还减少部分对应的现金价值"}', '条款中无加保条款约定', '{"支持": "是", "规则": "投保人与被保险人不为同一人时，投保人有权指定第二投保人", "指定条件": "(1)须经配偶、被保险人及第二投保人本人书面同意；(2)第二投保人与被保险人须有保险利益；(3)指定行为合法有效且不侵害其他继承人权益", "生效条件": "投保人身故后，第二投保人须在知道或应当知道投保人身故后两年内向保险公司提出变更投保人申请，经审核同意后方可成为新投保人", "不能成为投保人情形": "(1)不愿成为投保人；(2)在投保人身故时已身故或宣告死亡；(3)与投保人在同一事件', 979.66, '{"17周岁及以前身故": "取以下两项较大者：(1)所交保险费（按基本保险金额所确定的年交保费×已交费年度数）；(2)现金价值", "18周岁后身故且交费期未满": "取以下两项较大者：(1)所交保险费×比例（18-40周岁160%，41-60周岁140%，61周岁以上120%）；(2)现金价值", "18周岁后身故且交费期已满": "取以下三项较大者：(1)所交保险费×比例（18-40周岁160%，41-60周岁140%，61周岁以上120%）；(2)现金价值；(3)有效保险金额"}'); -- 复星保德信星盈家（朱雀版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, cross_generation, min_premium, death_payout_rule) VALUES (690, 1, 70, 1, 80.00, 5.00, 2.5, '[]', '{"规则1": "合同生效或最后一次复效之日起满5年后方可申请减保", "规则2": "每个保单年度累计减少的基本保险金额之和不得超过本合同生效时基本保险金额的20%", "规则3": "基本保险金额减少后，基本保险金额和保险费不得低于减保当时规定的最低标准", "减保效果": "基本保险金额减少的部分视为退保，退还减少部分对应的现金价值"}', '条款中无加保条款约定', '不支持。条款中无第二投保人相关约定', 1, 932.94, '{"17周岁及以前身故": "取以下两项较大者：(1)所交保险费（按基本保险金额所确定的年交保费×已交费年度数）；(2)现金价值", "18周岁后身故且交费期未满": "取以下两项较大者：(1)所交保险费×比例（18-40周岁160%，41-60周岁140%，61周岁以上120%）；(2)现金价值", "18周岁后身故且交费期已满": "取以下三项较大者：(1)所交保险费×比例（18-40周岁160%，41-60周岁140%，61周岁以上120%）；(2)现金价值；(3)有效保险金额"}'); -- 复星保德信星盈家（火凤版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (691, 1, 70, 1, 80.00, 5.00, 2.0, '[]', '{"规则1_时间要求": "合同生效或最后一次复效之日起满5年方可申请减保", "规则2_额度限制": "每个保单年度累计减少的基本保险金额之和不得超过合同生效时基本保险金额的20%", "规则3_最低标准": "减少后基本保险金额和保险费不得低于减保当时公司规定的最低标准", "规则4_退保处理": "基本保险金额减少的部分视为退保，按减少后的基本保险金额承担保险责任，退还减少部分对应的现金价值"}', '条款中未明确约定加保规则（基本保险金额变更仅涉及减少）', '支持第二投保人功能。投保人与被保险人不同一时，投保人可书面指定第二投保人，须经配偶、被保险人及第二投保人书面同意。被保险人年满18周岁可指定被保险人本人及直系亲属（配偶、成年子女、父母）；未满18周岁仅可指定被保险人父母。第二投保人须在知道投保人身故后两年内申请变更', 30.0, '{"说明": "分三档给付，取较大值", "到达年龄17周岁及以前": "所交保险费 与 现金价值 两者较大者", "到达年龄18周岁及以后且交费期间未满": "所交保费×对应比例 与 现金价值 两者较大者", "到达年龄18周岁及以后且交费期间已满": "所交保费×对应比例、现金价值、有效保险金额 三者较大者", "比例表": {"18-40周岁": "160%", "41-60周岁": "140%", "61周岁以上": "120%"}, "所交保费计算": "被保险人身故或全残时基本保险金额所确定的'); -- 复星保德信星盈家（玄武版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (692, 1, 70, 1, 80.00, 5.00, 3.0, '[]', '{"规则1_时间要求": "合同生效或最后一次复效之日起满5年方可申请减保", "规则2_额度限制": "每个保单年度累计减少的基本保险金额之和不得超过合同生效时基本保险金额的20%", "规则3_最低标准": "基本保险金额减少后，基本保险金额和保险费不得低于减保当时公司规定的最低标准", "规则4_退保处理": "基本保险金额减少的部分视为退保，按减少后的基本保险金额承担保险责任，退还减少部分对应的现金价值"}', '条款中未明确约定加保规则（基本保险金额变更仅涉及减少）', '条款中未提及第二投保人功能', 30.0, '{"说明": "分三档给付，取较大值", "到达年龄17周岁及以前": "所交保险费 与 现金价值 两者较大者", "到达年龄18周岁及以后且交费期间未满": "所交保费×对应比例 与 现金价值 两者较大者", "到达年龄18周岁及以后且交费期间已满": "所交保费×对应比例、现金价值、有效保险金额 三者较大者", "比例表": {"18-40周岁": "160%", "41-60周岁": "140%", "61周岁以上": "120%"}, "所交保费计算": "被保险人身故或全残时基本保险金额所确定的'); -- 复星保德信星盈家（虎啸版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (693, 1, 70, 1, 80.00, 5.00, 2.5, '[]', '{"规则1_时间要求": "合同生效或最后一次复效之日起满5年方可申请减保", "规则2_额度限制": "每个保单年度累计减少的基本保险金额之和不得超过合同生效时基本保险金额的20%", "规则3_最低标准": "基本保险金额减少后，基本保险金额和保险费不得低于减保当时公司规定的最低标准", "规则4_退保处理": "基本保险金额减少的部分视为退保，按减少后的基本保险金额承担保险责任，退还减少部分对应的现金价值"}', '条款中未明确约定加保规则（基本保险金额变更仅涉及减少）', '条款中未提及第二投保人功能', 30.0, '{"说明": "分三档给付，取较大值", "到达年龄17周岁及以前": "所交保险费 与 现金价值 两者较大者", "到达年龄18周岁及以后且交费期间未满": "所交保费×对应比例 与 现金价值 两者较大者", "到达年龄18周岁及以后且交费期间已满": "所交保费×对应比例、现金价值、有效保险金额 三者较大者", "比例表": {"18-40周岁": "160%", "41-60周岁": "140%", "61周岁以上": "120%"}, "所交保费计算": "被保险人身故或全残时基本保险金额所确定的'); -- 复星保德信星盈家（青鸾版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, death_payout_rule) VALUES (694, 1, 70, 1, 80.00, 5.00, 3.0, '[]', '合同生效或最后一次复效之日起满5年后可申请减保。每个保单年度累计减少的基本保险金额之和不得超过本合同生效时基本保险金额的20%。基本保险金额减少后，基本保险金额和保险费不得低于减保当时公司规定的最低标准。减保部分视为退保，退还减少部分对应的现金价值。', '条款中未提及加保权益。', '{"是否支持": "否", "规则说明": "条款中未设第二投保人条款。"}', '{"保障类型": "身故或全残保险金", "18周岁前身故或全残": "取（1）所交保险费 与 （2）现金价值 两者较大者", "18周岁后身故或全残（交费期间未满）": "取（1）所交保险费乘以对应比例 与 （2）现金价值 两者较大者", "18周岁后身故或全残（交费期间已届满）": "取（1）所交保险费乘以对应比例、（2）现金价值、（3）有效保险金额 三者最大者", "赔付比例": "18周岁-40周岁：160%；41周岁-60周岁：140%；61周岁以上：120%", "备注": "身故保险金和全残'); -- 复星保德信星盈家（龙腾版）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, death_payout_rule) VALUES (695, 1, 70, 1, 80.00, 5.00, 3.5, '[]', '条款中未明确使用"减保"一词。投保规则未专门列出减保规则。可通过基本保险金额变更（减少）实现，但需以书面形式申请并经审核同意。', '支持加保。（1）被保险人年满70周岁前的首个保单周年日（不含）前，可通过额外支付一次性保险费增加基本保险金额，保费按增加时年龄计算；（2）交费年期未满的，在第2个保单周年日（含）至第5个保单周年日（不含）前，可增加基本保险金额，保费按原投保年龄计算，须补交保险费，每年增加以原基本保险金额的50%为限。已变更为减额交清或保费已豁免的不可加保。', '{"是否支持": "否", "规则说明": "条款中未设第二投保人条款。"}', '{"保障类型": "身故或全残保险金", "18周岁前身故或全残": "取（1）实际交纳的保险费（不计息） 与 （2）现金价值 两者较大者", "18周岁后身故或全残（交费年期未满）": "取（1）实际交纳的保险费乘以对应比例 与 （2）现金价值 两者较大者", "18周岁后身故或全残（交费年期已届满）": "取（1）实际交纳的保险费乘以对应比例、（2）现金价值、（3）基本保险金额×(1+3.5%)^(保单年度数-1) 三者最大者", "赔付比例": "18周岁-40周岁：160%；41周岁-60周岁：1'); -- 复星保德信星财神终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_rule_text, add_rule_text, second_applicant_rule, death_payout_rule) VALUES (696, 1, 70, 1, 80.00, 5.00, 3.25, '[]', '条款中未明确使用"减保"一词。可通过基本保险金额变更（减少）实现，条款8条规定可以书面形式申请减少基本保险金额，减少后的基本保险金额不得低于投保时规定的最低标准，减少部分按退保处理。', '条款中未提及加保权益。', '{"是否支持": "否", "规则说明": "条款中未设第二投保人条款。"}', '{"保障类型": "身故保险金（不含全残保障）", "18周岁前身故": "取（1）已支付的保险费 与 （2）现金价值 两者较大者", "18周岁后身故（交费期间内）": "取（1）已支付的保险费乘以对应比例 与 （2）现金价值 两者较大者", "18周岁后身故（已超出交费期间）": "取（1）已支付的保险费乘以对应比例、（2）现金价值、（3）基本保险金额×(1+3.25%)^(保单年度数-1) 三者最大者", "赔付比例": "30天-17周岁：100%；18周岁-40周岁：160%；41周岁-60周岁'); -- 复星保德信爱意传承D款终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list, reduction_start_year, reduction_rule_text, add_rule_text, second_applicant_rule, min_premium, death_payout_rule) VALUES (778, 1, 70, 1, 80.00, 5.00, 0, '[]', 5, '自第5个保单周年日起可申请减保，每保单年度累计减少的基本保险金额不得超过投保时基本保险金额的20%', '未明确', '犹豫期满后可指定第二投保人；被保险人不满18岁或无完全民事行为能力时，指定其父亲或母亲；被保险人满18岁且有完全民事行为能力时，指定被保险人本人', 24.21, '18岁前身故：取累计已交保费（不计息）与现金价值的较大者；18岁后身故：给付基本保险金额'); -- 瑞泰鸿利传世（2025）终身寿险
INSERT INTO whole_life_product (product_id, reduction_rule_type, max_add_age, add_premium_rule, loan_ratio, loan_rate, increase_rate, support_age_list) VALUES (789, 1, 70, 1, 80.00, 5.00, 0, '[]'); -- 长城任我行3.0两全保险
