INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, universal_account_name, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (968, 1, 0.085, '[]', 0, 1, '[3, 5, 10]', '[3, 5, 10]', '生存年金+满期保险金', '按年领取或按月领取（投保时约定，领取开始后不可变更）', 100000.0, '被保险人身故时，按以下二项中金额较高的一项给付身故保险金：（1）被保险人身故时，本合同基本保险金额所对应的现金价值；（2）被保险人身故时，本合同基本保险金额所对应的已交保险费。含自动垫交保费的，已交保费包含垫交部分。', 1, '默认万能账户', '趸交/3年交/5年交：第5个保单周年日；10年交：第10个保单周年日', '按年或按月', '{"按年领取_趸交": "自第5个保单周年日起，每年按基本保险金额的2倍给付", "按年领取_3年交": "第5-6周年按基本保险金额；第7周年起按基本保险金额的2倍给付", "按年领取_5年交": "第5-9周年按基本保险金额；第10周年起按基本保险金额的2倍给付", "按年领取_10年交": "第10-11周年按基本保险金额；第12周年起按基本保险金额的2倍给付", "按月领取_趸交": "自第5个保单周年日起，每月按基本保险金额的2倍×8.5%给付", "按月领取_3年交": "第5-6年每月按基本', '{"趸交_40岁男": "421元/万元基本保额", "5年交_40岁男": "421元/万元基本保额", "10年交_40岁男": "841元/万元基本保额", "3年交_40岁男": "424元/万元基本保额"}'); -- 中英人寿悦活人生年金保险B款（分红型）
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (969, 1, 0.085, '[]', 0, 1, '[]', '[]', '未明确', '按年领取或按月领取，投保时约定，年金开始领取后不得变更', 20000.0, '未明确', '未明确', '未明确', '未明确', '{"说明": "以下为每万元基本保险金额对应的年交保费，单位：元", "40岁男性": {"3年交": "290", "5年交": "482"}, "40岁女性": {"3年交": "294", "5年交": "489"}, "0岁男性": {"3年交": "297", "5年交": "493"}}'); -- 中英人寿悦活人生年金保险（分红型）
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, universal_account_name, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (970, 0, 0.085, '[]', 0, 1, '[5]', '[5]', '年金+特别年金', '按年领取（每保单周年日给付），领取方式在投保时约定', 16000000.0, '（1）在年满66周岁后的首个保单周年日结束前（含）身故：按现金价值与已缴保费中较高者给付。（2）在年满66周岁后的首个保单周年日结束后身故：按身故时现金价值给付。含自动垫缴保费的，已缴保费包含垫缴部分。', 1, '默认万能账户', '第5个保单周年日', '按年（每保单周年日给付）', '{"第5个保单周年日": "按基本保险金额×150%一次性给付年金", "第6个保单周年日起至年满60岁前": "每年按基本保险金额×30%给付年金", "年满60岁起至保险期间届满": "每年按基本保险金额×50%给付年金", "66岁生日当天": "额外一次性给付特别年金=基本保险金额对应的已缴保费"}', '{"趸交_30岁男": "15934.5元/万元基本保额", "3年交_30岁男": "5937.7元/万元基本保额", "5年交_30岁男": "3679.5元/万元基本保额", "10年交_30岁男": "1992.4元/万元基本保额"}'); -- 中英人寿晶彩人生年金保险（分红型）
