INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1035, 1, 0.085, '[]', 0, 1, '[55, 60, 65, 70]', '[55, 60, 65, 70]', '养老年金（现金红利型分红，支持四种领取计划）', '按年领取或按月领取。提供计划一、计划二、计划三、计划四四种养老年金领取计划（投保时约定一种）', 30000.0, '{"领取日前身故": "按累计已交纳保险费与基本保险金额对应的现金价值中的较大者给付", "领取日后身故_计划一二三四": "如累计已交保费>累计已给付养老年金金额，按差额（不计息）给付；否则不承担身故保险金责任", "领取日后身故_计划二": "不承担给付身故保险金的责任"}', 0, '被保险人达到养老年金起始领取年龄后的首个保单周年日', '按年或按月', '{"计划一": "终身按基本保险金额100%（年领）或8.5%（月领）", "计划二": "终身按基本保险金额100%（年领）或8.5%（月领）", "计划三": "81岁前按基本保险金额100%（年领）或8.5%（月领），81岁起（含）按基本保险金额50%（年领）或4.25%（月领）", "计划四": "71岁前按基本保险金额50%（年领）或4.25%（月领），71岁起（含）至81岁前按基本保险金额100%（年领）或8.5%（月领），81岁起（含）按基本保险金额150%（年领）或12.75%（月领）"}'); -- 复星保德信星海赢家青鸾版养老年金保险 （分红型）
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1036, 1, 0.085, '[]', 0, 0, '[5]', '[5]', '定期年金（非养老年金，第5个保单周年日起领取至保险期间届满）', '按年领取或按月领取（投保时约定，首个年金领取日前可变更领取频率，领取开始后不可变更）', 30000.0, '保险期间内被保险人身故，按实际交纳保费（不计息）与现金价值中的较大者给付身故保险金', 0, '第5个保单周年日（投保后第5年）', '按年或按月', '{"按年领取": "基本保险金额的100%", "按月领取": "基本保险金额的8.5%"}'); -- 复星保德信星颐定期年金保险（分红型）
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1037, 0, 0.085, '[]', 0, 1, '[5]', '[5]', '生存年金（终身领取）', '现金领取、累积生息、购买交清增额保险', 30000.0, '被保险人身故时，按以下两项金额中的较大者给付身故保险金，合同效力终止：(1)被保险人身故时合同的累计已交纳保险费（年交保费x已交费年度数，不计息）；(2)被保险人身故时合同基本保险金额对应的现金价值。上述保险责任不包括因红利分配产生的相关利益。', 0, '第5个保单周年日', '按年领取（年领）', '{"按年领取": "自第5个保单周年日（含）起，每年按基本保险金额的100%给付年金，至被保险人身故"}'); -- 复星保德信星颐年金保险（分红型）
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1038, 0, 0.085, '[]', 0, 0, '[5]', '[5]', '生存年金+满期金（定期）', '现金领取、累积生息', 30000.0, '被保险人身故时，按以下两项金额中的较大者给付身故保险金，合同效力终止：(1)被保险人身故时合同的累计已交纳保险费（年交保费x已交费年度数，不计息）；(2)被保险人身故时合同基本保险金额对应的现金价值。', 0, '第5个保单周年日', '按年领取或按月领取（投保时约定，首个年金领取日前可变更频率，之后不可变更）', '{"按年领取": "自第5个保单周年日（含）起至保险期间届满日（不含），每年按基本保险金额的100%给付年金", "按月领取": "自第5个保单周年日（含）起至保险期间届满日（不含），每月按基本保险金额的8.5%给付年金"}'); -- 复星保德信星颐朱雀版定期年金保险（分红型）
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1039, 0, 0.085, '[]', 0, 1, '[5]', '[5]', '生存年金（终身领取）', '现金领取、累积生息、购买交清增额保险', 30000.0, '被保险人身故时，按以下两项金额中的较大者给付身故保险金，合同效力终止：(1)被保险人身故时合同的累计已交纳保险费（年交保费x已交费年度数，不计息）；(2)被保险人身故时合同基本保险金额对应的现金价值。上述保险责任不包括因红利分配产生的相关利益。', 0, '第5个保单周年日', '按年领取（年领）', '{"按年领取": "自第5个保单周年日（含）起，每年按基本保险金额的100%给付年金，至被保险人身故"}'); -- 复星保德信星颐朱雀版年金保险（分红型）
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1140, 1, 0.085, '[30]', 0, 1, '[60]', '[60]', '养老年金', '按年领取或按月领取，投保时约定，首次领取日前可变更', '首次养老年金领取日零时前身故：按累计所交保险费（不计息）与现金价值的较大者给付；首次养老年金领取日零时后身故：不承担身故保险金责任（保证给付期内身故则一次性给付保证给付期限内应给付总额与累计已给付的差额）。', 0, '祝福保险金：第5个保单周年日（投保年龄不超54岁）；养老年金：60周岁后首个保单周年日（或首个保单周年日）', '养老年金：按年或按月；祝福保险金：按年', '养老年金年领：基本保险金额；月领：对应保单年度年领金额的8.5%。祝福保险金：基本保险金额的30%。'); -- 瑞泰尊享一生年金保险（分红型）
