INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (1245, 1, 0.085, '[]', 0, 0, '[]', '[]', '年金保险（非养老年金）', '按年领取或按月领取（投保时选择，载明于保险单上）', 100000.0, '被保险人身故时，取本合同基本保险金额所对应的现金价值与已交保险费两者中的较大者给付，合同效力终止', 0, '{"趸交或3年交": "关爱金于第5个保单周年日领取，生存年金自第6个保单周年日起领", "5年交": "关爱金于第6个保单周年日领取，生存年金自第7个保单周年日起领", "10年交": "关爱金于第10个保单周年日领取，生存年金自第11个保单周年日起领"}', '按年领取为每个保单周年日，按月领取为每个保单周月日', '{"关爱金（按年领取）": "基本保险金额×10%（一次性给付）", "关爱金（按月领取）": "基本保险金额×10%×8.5%（最多12期）", "生存年金（按年领取）": "基本保险金额所对应的已交保险费×2%", "生存年金（按月领取）": "基本保险金额所对应的已交保险费×2%×8.5%", "满期保险金": "基本保险金额所对应的已交保险费×102%"}', '0岁男趸交：422元/千元保费；0岁女趸交：422元/千元保费；0岁男3年交：671元/千元保费；0岁女3年交：671元/千元保费；0岁男5年交：1089元/千元保费；0岁女5年交：1090元/千元保费；0岁男10年交：3565元/千元保费；0岁女10年交：3567元/千元保费；40岁男趸交：421元/千元保费；40岁男3年交：666元/千元保费；40岁男5年交：1079元/千元保费；40岁男10年交：3525元/千元保费；40岁女趸交：421元/千元保费；40岁女3年交：668元/千元保费；40岁女5年'); -- 中英人寿悦活人生年金保险D款
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, universal_account_name, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (1246, 1, 0.085, '[]', 0, 1, '[]', '[]', '年金保险（非养老年金）', '按年领取或按月领取（投保时选择，载明于保险单上）', 30000.0, '被保险人身故时，取本合同基本保险金额所对应的现金价值与已交保险费两者中的较大者给付，合同效力终止', 1, '默认万能账户', '{"趸交或3年交或5年交": "第5个保单周年日起领", "6年交": "第6个保单周年日起领", "10年交": "第10个保单周年日起领"}', '按年领取为每个保单周年日，按月领取为每个保单周月日', '{"生存年金（按年领取）": "基本保险金额", "生存年金（按月领取）": "基本保险金额×8.5%"}', '需参照费率表xlsx文件（04_费率表.xlsx），费率表按性别、年龄、交费期间列示每千元保费对应基本保险金额'); -- 中英人寿悦活人生年金保险（互联网）
