INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, universal_account_name, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (1249, 1, 0.085, '[]', 0, 1, '[55, 60, 65, 70]', '[55, 60, 65, 70]', '养老年金（方案一/方案二）', '按年领取或按月领取（投保时约定，领取开始后不可变更）', 8000.0, '{"方案一": "养老年金开始领取日前身故：按现金价值与已交保费中较高者给付。养老年金开始领取日（含）起不再承担身故保险金责任。", "方案二": "领取日前身故：按现金价值与已交保费中较高者给付。领取日后身故：一次性给付已交保费扣减累计已领取养老年金后的余额；若余额≤0，不承担给付责任。"}', 1, '默认万能账户', '被保险人达到养老年金开始领取年龄后的首个保单周年日', '按年或按月', '{"按年领取": "按当时的基本保险金额给付养老年金", "按月领取": "按当时的基本保险金额×0.085给付养老年金"}', '{"方案一_趸交_55岁女": "221元/万元基本保额", "方案一_趸交_60岁男": "299元/万元基本保额", "方案一_3年交_55岁女": "640元/万元基本保额", "方案一_5年交_55岁女": "1034元/万元基本保额", "方案一_10年交_55岁女": "1930元/万元基本保额", "方案一_趸交_60岁女": "277元/万元基本保额", "方案一_5年交_60岁男": "1395元/万元基本保额", "方案二_趸交_55岁女": "226元/万元基本保额", "方案二_5'); -- 中英人寿福临门养老年金保险
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (1250, 1, 0.085, '[]', 0, 1, '[55, 60, 65, 70]', '[55, 60, 65, 70]', '养老年金', '按年领取或按月领取（投保时选择，载明于保险单上）', 12000.0, '{"方案一": "养老年金开始领取日前身故，取现金价值与已交保费中较大者；养老年金开始领取日（含）起不承担身故保险金（保证领取期内身故给付保证领取额度扣除已领余额）", "方案二": "养老年金开始领取日前身故，取现金价值与已交保费中较大者；养老年金开始领取日（含）后身故，给付已交保费减累计已领年金余额（余额<=0时不给付）"}', 0, '被保险人达到养老年金开始领取年龄后的首个保单周年日', '按年领取为每个保单周年日，按月领取为每个保单周月日', '{"方案一（按年领取）": "基本保险金额", "方案一（按月领取）": "基本保险金额×0.085", "方案二（按年领取）": "基本保险金额", "方案二（按月领取）": "基本保险金额×0.085"}', '0岁女趸交方案一55周岁起领：640元/千元保费；0岁女趸交方案二55周岁起领：653元/千元保费；0岁男趸交方案一60周岁起领：864元/千元保费；0岁男趸交方案二60周岁起领：923元/千元保费；0岁女3年交方案一55周岁起领：1034元/千元保费；0岁女3年交方案一60周岁起领：1395元/千元保费；0岁男3年交方案一60周岁起领：1086元/千元保费；0岁男5年交方案一60周岁起领：1753元/千元保费；0岁男10年交方案一60周岁起领：2604元/千元保费；0岁男20年交方案一60周岁起领：45'); -- 中英人寿福临门养老年金保险（个人养老年金）
