INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule, typical_rate_example) VALUES (1254, 1, 0.085, '[]', 0, 0, '[1, 2, 3, 55, 60]', '[1, 2, 3, 55, 60]', '养老年金', '按年领取或按月领取两种（养老年金开始领取日前可变更，领取后不可变更）', 50000.0, '85周岁后的首个保单周年日（含）之前身故：给付基本保险金额所对应的已交保险费，合同终止。85周岁后的首个保单周年日（不含）之后身故：取以下两项中金额较高者给付——(1)身故时合同的现金价值；(2)基本保险金额所对应的已交保险费扣减累计已领取养老年金后的余额，合同终止。', 0, '根据选择的开始领取日，可选合同生效后的首个保单周年日、交费期间届满后的首个保单周年日、或达到法定退休年龄后的首个保单周年日', '按年或按月', '按年领取：取min(基本保险金额×已经过完整保单年度数, 基本保险金额×交费年期数)给付养老年金。按月领取：取min(基本保险金额×8.5%×已经过完整保单年度数, 基本保险金额×8.5%×交费年期数)给付养老年金。此外有满期保险金=基本保险金额×交费年期数。', '60岁男性，趸交，生效后首个保单周年日开始领取：296元/万元保额。60岁男性，3年交，生效后首个保单周年日开始领取：282元/万元保额。60岁男性，3年交，交费期满后开始领取：294元/万元保额。60岁男性，5年交，交费期满后开始领取：286元/万元保额。60岁女性，趸交，生效后首个保单周年日开始领取：307元/万元保额。60岁女性，3年交，生效后首个保单周年日开始领取：294元/万元保额。'); -- 中英人寿福相伴养老年金保险
