INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, first_return_time, return_frequency, return_amount_rule) VALUES (1378, 0, 0.085, '[]', 0, 1, '[55, 60, 65, 70]', '[55, 60, 65, 70]', '养老年金', '提供计划一、计划二、计划三、计划四四种领取计划，投保时选择', 30000.0, '{"领取前身故": "按实际交纳保险费（不计息）与现金价值较大者给付", "领取后身故_计划一_三_四": "已交保费大于累计已给付养老年金金额的，给付差额；已交保费小于等于已给付金额的，不承担身故保险金", "领取后身故_计划二": "不承担给付身故保险金的责任"}', '养老年金起始领取年龄后的首个保单周年日', '年领或月领（投保时选择，首个领取日前可申请变更频率）', '{"计划一": {"年领": "每期为基本保险金额的100%", "月领": "每期为基本保险金额的8.5%"}, "计划二": {"年领": "每期为基本保险金额的100%", "月领": "每期为基本保险金额的8.5%"}, "计划三": {"85周岁前": {"年领": "每期为基本保险金额的100%", "月领": "每期为基本保险金额的8.5%"}, "85周岁后": {"年领": "每期为基本保险金额的30%", "月领": "每期为基本保险金额的2.55%"}}, "计划四": {"前10年'); -- 复星保德信星海赢家（朱雀版）养老年金保险
