INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, first_return_time, return_frequency, return_amount_rule) VALUES (1384, 1, 0.085, '[20]', 0, 1, '[55, 60, 65, 70]', '[55, 60, 65, 70]', '养老年金（固收型，提供计划一和计划二两种养老年金领取计划，均含保证给付期间）', '按年领取或按月领取（投保时约定，首个养老年金领取日前可变更领取频率，领取开始后不可变更）', 30000.0, '{"领取日前身故": "按实际交纳保费（不计息）与现金价值中的较大者给付", "领取日后身故": "不承担给付身故保险金的责任（通过保证给付期间内的一次性差额给付保障受益人权益）"}', '被保险人达到养老年金起始领取年龄后的首个保单周年日', '按年或按月', '{"按年领取": "基本保险金额的100%", "按月领取": "基本保险金额的8.5%"}'); -- 复星保德信星海赢家（龙腾版）养老年金保险
