INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, universal_account_name, first_return_time, return_frequency, return_amount_rule) VALUES (1386, 0, 0.085, '[15]', 0, 0, '[55, 60, 65]', '[55, 60, 65]', '养老年金（定期领取至80周岁）', '现金领取', 100000.0, '（1）首个养老年金领取日零时前身故：按实际交纳保险费（不计息）与现金价值两者较大者给付身故保险金，合同效力终止；（2）首个养老年金领取日零时后身故：不承担身故保险金责任。保证给付期间内身故：按保证给付期间内应给付的养老年金总额与累计已给付的养老年金金额两者之间的差额（不计息）一次性给付养老年金，合同效力终止。', 1, '默认万能账户', '养老年金起始领取年龄后的首个保单周年日（55/60/65周岁后的首个保单周年日）', '年领或月领，投保时选择', '{"按年领取": "自首个养老年金领取日起，每期养老年金领取金额为本合同的基本保险金额", "按月领取": "每期养老年金领取金额为本合同的基本保险金额的8.5%"}'); -- 复星保德信星福家（定期版）养老年金保险
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1387, 1, 0.085, '[]', 0, 0, '[40, 50, 55, 65]', '[40, 50, 55, 65]', '生存年金（领取至106周岁）', '现金领取、购买交清增额保险（月领不支持购买交清增额保险；年满70周岁后不支持购买交清增额保险）', 30000.0, '分两种情形：（一）首个年金领取日不晚于55周岁后首个保单周年日：55周岁前身故按累计已交保费与现金价值较大者给付；55周岁后身故按基本保额x10（年领）或基本保额x10x8.5%x12（月领）与已给付年金差额给付，差额为零则不给付。（二）首个年金领取日在55周岁后首个保单周年日之后：首个领取日前身故按累计已交保费与现金价值较大者给付；首个领取日后身故同样按基本保额x10总额与已给付年金差额给付。', 0, '首个年金领取日，取决于交费期间与约定领取年龄二者取大值。趸交/3年/5年交：第7个保单周年日或约定领取年龄后首个保单周年日；10年交：第10个保单周年日或约定领取年龄后首个保单周年日；15年交：第15个保单周年日或约定领取年龄后首个保单周年日；20年交：第20个保单周年日或约定领取年龄后首个保单周年日', '年领或月领，投保时选择，首个年金领取日前可变更', '{"按年领取": "自首个年金领取日起，每期年金领取金额为基本保险金额的100%", "按月领取": "每期年金领取金额为基本保险金额的8.5%"}'); -- 复星保德信星颐2.0年金保险
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1388, 1, 0.085, '[]', 0, 1, '[3, 5, 10, 15, 20]', '[3, 5, 10, 15, 20]', '生存年金（终身领取）', '现金领取、购买交清增额保险（月领不支持购买交清增额保险；年满70周岁后不支持购买交清增额保险）', 30000.0, '计划一：首个年金领取日前身故按累计已交保费与现金价值较大者给付；首个年金领取日后身故按累计已交保费给付身故保险金。计划二：首个年金领取日在55周岁后首个保单周年日前（含）且55周岁后首个保单周年日前身故按累计已交保费与现金价值较大者给付；首个年金领取日在55周岁后首个保单周年日前（含）且55周岁后首个保单周年日后身故不给付身故保险金；首个年金领取日在55周岁后首个保单周年日后且首个领取日前身故按累计已交保费与现金价值较大者给付；首个年金领取日在55周岁后首个保单周年日后且首个领取日后身故不给付身故保险金。', 0, '趸交/3年交/5年交为第5个保单周年日；10年交为第10个保单周年日；15年交为第15个保单周年日；20年交为第20个保单周年日', '年领或月领，投保时选择，首个年金领取日前可变更', '{"按年领取": "自首个年金领取日起，每期年金领取金额为领取当时基本保险金额的100%", "按月领取": "每期年金领取金额为领取当时基本保险金额的8.5%"}'); -- 复星保德信星颐3.0年金保险
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type) VALUES (1389, 0, 0.085, '[]', 0, 1, '[]', '[]', '固收型'); -- 复星保德信星颐养老年金保险
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1390, 1, 0.085, '[20]', 0, 1, '[55, 60, 65, 70]', '[55, 60, 65, 70]', '养老年金（含身故或全残保险金）', '年领或月领（投保时选择，可申请变更）', 20000.0, '（1）被保险人于首个养老年金领取日零时前身故或全残：按现金价值与实际交纳保险费两项中的较大者给付身故或全残保险金，合同效力终止。（2）被保险人于首个养老年金领取日零时后身故或全残：不承担给付身故或全残保险金责任（但保证给付期间内身故或全残的，一次性给付保证给付期间内应付养老年金总额与累计已给付养老年金金额的差额，不计息，合同效力终止）。', 0, '首个养老年金领取日（养老年金起始领取年龄后的首个保单周年日）', '按年或按月', '{"养老年金_按年领取": "每期养老年金领取金额为本合同的基本保险金额", "养老年金_按月领取": "每期养老年金领取金额为本合同基本保险金额的8.5%", "保证给付期间差额": "被保险人在保证给付期间内身故或全残，一次性给付保证给付期间内应给付养老年金总额与累计已给付养老年金金额的差额（不计息）"}'); -- 复星保德信星颐（优享版）养老年金保险
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1391, 1, 0.085, '[]', 0, 1, '[55, 60, 65]', '[55, 60, 65]', '养老年金（含身故保险金）', '年领或月领（投保时选择，可申请变更）', 20000.0, '如被保险人身故，按现金价值与实际交纳保险费两项中的较大者给付身故保险金，合同效力终止。', 0, '首次养老年金领取日（养老年金起始领取年龄后的首个保单周年日）', '按年或按月', '{"养老年金_按年领取": "每期养老年金领取金额为本合同的基本保险金额", "养老年金_按月领取": "每期养老年金领取金额为本合同基本保险金额的8.4%"}'); -- 复星保德信福寿齐添养老年金保险
INSERT INTO annuity_product (product_id, support_monthly, monthly_coefficient, guarantee_options, support_increase, is_lifelong, start_age_female, start_age_male, annuity_type, payout_rule_text, min_premium, death_benefit_rule, universal_account_linked, first_return_time, return_frequency, return_amount_rule) VALUES (1392, 0, 0.085, '[]', 0, 1, '[10]', '[10]', '特别生存金+关爱生存金+年金+身故保险金', '按年领取（仅年领）', 30000.0, '如被保险人身故，按以下两项金额中的较大者给付身故保险金，合同效力终止：（1）被保险人身故时本合同的现金价值；（2）被保险人身故时本合同实际交纳的保险费（不计息）与累计已领取的生存金之差。', 0, '趸交/3年/5年交：第5个保单周年日；10年交：第10个保单周年日', '按年', '{"特别生存金": "趸交/3年交/5年交：第5-9个保单周年日每年给付，按实际交纳保险费（不计息）的10%给付；10年交：第10-14个保单周年日每年给付，按实际交纳保险费（不计息）的10%给付", "关爱生存金": "第26-30个保单周年日，按实际交纳保险费（不计息）的10%给付", "年金": "自第10个保单周年日（含）起，按基本保险金额的100%给付年金，直至被保险人身故"}'); -- 复星保德信福寿齐添（庆典版）年金保险
